#!/usr/bin/env python3
"""Emit report macros for the patched-node validation-cost benchmark.

Every value is PARSED from the run's own SUMMARY line — the benchmark prints it precisely so
that no figure has to be retyped. A number typed into a script is a number that silently
stops matching the run it claims to describe.

Reads   evidence/btc_las_bench/latest/summary.txt
Writes  report/latex/generated/btclasbenchmacros.tex

Usage: gen_btc_las_bench_data.py [--bench DIR] [--out FILE]
"""
import argparse
import pathlib
import sys

HEADER = (
    "% GENERATED by scripts/gen_btc_las_bench_data.py -- DO NOT EDIT.\n"
    "% Values parsed from the benchmark's own SUMMARY line in\n"
    "% evidence/btc_las_bench/latest/. Never hand-type a figure here.\n"
    "% Write-up: docs/03-results/BTC_LAS_CONSENSUS_BENCHMARK.md\n"
    "%\n"
    "% CAVEATS THAT TRAVEL WITH THESE NUMBERS (see the write-up):\n"
    "%   (0) the curve baseline is a pinned libsecp256k1-zkp, a FORK of libsecp256k1 --\n"
    "%       NOT the library Bitcoin Core vendors, so these are not Core's numbers;\n"
    "%   (a) the security of the consensus modification is NOT analysed;\n"
    "%   (b) the security levels are NOT matched -- the node runs Simplified Dilithium-III\n"
    "%       while secp256k1 matches Dilithium-II, so the ratios OVERSTATE the rule's cost.\n"
)


def parse_summary(path: pathlib.Path) -> dict:
    text = path.read_text().strip()
    if not text.startswith("SUMMARY "):
        sys.exit(f"{path}: does not start with 'SUMMARY ' -- refusing to guess")
    out = {}
    for token in text[len("SUMMARY "):].split():
        if "=" not in token:
            sys.exit(f"{path}: malformed token {token!r}")
        k, v = token.split("=", 1)
        out[k] = v
    return out


def fmt(value: str, dp: int) -> str:
    """Format a measured number, thousands-separated for LaTeX."""
    f = float(value)
    s = f"{f:,.{dp}f}"
    return s.replace(",", "{,}")


def main() -> None:
    repo = pathlib.Path(__file__).resolve().parent.parent
    ap = argparse.ArgumentParser()
    ap.add_argument("--bench", type=pathlib.Path,
                    default=repo / "evidence/btc_las_bench/latest")
    ap.add_argument("--out", type=pathlib.Path,
                    default=repo / "report/latex/generated/btclasbenchmacros.tex")
    args = ap.parse_args()

    summary = args.bench / "summary.txt"
    if not summary.exists():
        sys.exit(f"{summary} not found -- run scripts/run_btc_las_bench.sh first")
    s = parse_summary(summary)

    required = ["las_accept_us", "las_accept_sd", "las_reject_us",
                "schnorr_accept_us", "schnorr_accept_sd", "ecdsa_accept_us",
                "ratio_schnorr", "ratio_ecdsa", "reps", "iters", "las_param_set"]
    missing = [k for k in required if k not in s]
    if missing:
        sys.exit(f"{summary}: missing keys {missing}")

    # Reported as an observation, NOT gated on.
    #
    # ⚠ DO NOT turn this into a pass/fail check. That the reject path fails LATE — that a
    # rejection costs a full verification rather than an early bail-out — is established by
    # how the input is CONSTRUCTED (a valid signature against a different 32-byte digest, so
    # every stage before the final challenge comparison must run), not by how long it takes.
    # A timing ratio near 1 is a consequence of that design, not evidence for it, and gating
    # on it would dress the consequence up as proof while letting ordinary machine variation
    # abort the pipeline for no real reason.
    ratio_reject = float(s["las_reject_us"]) / float(s["las_accept_us"])

    lines = [HEADER]
    add = lines.append
    add(f"\\newcommand{{\\btcLasBenchReps}}{{{s['reps']}}}")
    add(f"\\newcommand{{\\btcLasBenchIters}}{{{s['iters']}}}")
    add(f"\\newcommand{{\\btcLasBenchSet}}{{{s['las_param_set']}}}")
    add(f"\\newcommand{{\\btcLasVerifyUs}}{{{fmt(s['las_accept_us'], 0)}}}")
    add(f"\\newcommand{{\\btcLasVerifySd}}{{{fmt(s['las_accept_sd'], 0)}}}")
    add(f"\\newcommand{{\\btcLasRejectUs}}{{{fmt(s['las_reject_us'], 0)}}}")
    add(f"\\newcommand{{\\btcSchnorrVerifyUs}}{{{fmt(s['schnorr_accept_us'], 1)}}}")
    add(f"\\newcommand{{\\btcSchnorrVerifySd}}{{{fmt(s['schnorr_accept_sd'], 1)}}}")
    add(f"\\newcommand{{\\btcEcdsaVerifyUs}}{{{fmt(s['ecdsa_accept_us'], 1)}}}")
    add(f"\\newcommand{{\\btcLasRatioSchnorr}}{{{fmt(s['ratio_schnorr'], 1)}}}")
    add(f"\\newcommand{{\\btcLasRatioEcdsa}}{{{fmt(s['ratio_ecdsa'], 1)}}}")
    add(f"\\newcommand{{\\btcLasRejectRatio}}{{{ratio_reject:.2f}}}")

    args.out.parent.mkdir(parents=True, exist_ok=True)
    args.out.write_text("\n".join(lines) + "\n")
    print(f"wrote {args.out.relative_to(repo)} from {summary.relative_to(repo)}")
    print(f"  LAS verify {s['las_accept_us']} us  vs Schnorr {s['schnorr_accept_us']} us "
          f"({s['ratio_schnorr']}x), reject/accept {ratio_reject:.2f}")


if __name__ == "__main__":
    main()
